K("Etiqueta de apertura", d="secuencia <?php que inicia código PHP en un archivo", u="indicar al intérprete dónde comienza el código PHP", mas="La etiqueta larga <?php es la forma recomendada de abrir código PHP. En un archivo PHP puro puede omitirse la etiqueta de cierre, lo que evita enviar accidentalmente espacios al final.", k=["<?php inicia un bloque de código PHP.", "La etiqueta larga funciona sin depender de short_open_tag.", "En archivos PHP puros suele omitirse la etiqueta de cierre."], sit="Un archivo comienza con la forma de apertura estándar y portable de PHP; ¿qué etiqueta escribes?", cod="<?php echo 'Inicio correcto';", h="abre PHP y muestra una confirmación", pr=("La etiqueta larga para iniciar PHP es ___.", "<?php"), ec="usar <? como etiqueta corta sin asegurar que esté habilitada", pr2=("La etiqueta de apertura larga empieza con los caracteres <?___.", "php"), out="Inicio correcto"),
K("Punto y coma", d="signo que termina la mayoría de las instrucciones PHP", u="separar instrucciones consecutivas con claridad", mas="Las instrucciones simples normalmente terminan con punto y coma. PHP permite omitirlo en la última instrucción antes de la etiqueta de cierre, pero mantenerlo hace que el código sea consistente.", k=["Una instrucción echo puede terminar con punto y coma.", "El punto y coma separa instrucciones simples.", "Las declaraciones de bloques como if no llevan punto y coma tras la llave final."], sit="Escribes dos instrucciones simples seguidas y necesitas cerrar cada una; ¿qué signo usas?", cod="<?php $n = 2; echo $n;", h="asigna un número y lo muestra en una instrucción separada", pr=("El signo que suele cerrar una instrucción PHP es ___.", ";"), ec="olvidar el punto y coma entre instrucciones", pr2=("En PHP, el separador usual de instrucciones simples es el punto y ___.", "coma"), out="2"),
K("Comentario de línea", d="anotación que empieza con // o # y no se ejecuta", u="dejar una explicación breve junto al código", mas="PHP ignora el texto de un comentario de línea. La forma // es común; # también sirve fuera de contextos especiales. Para bloques de texto se puede usar /* ... */.", k=["// inicia un comentario de una línea.", "# también puede iniciar un comentario de línea en PHP.", "El texto comentado no forma parte de la salida del programa."], sit="Quieres documentar una instrucción con una nota que el intérprete ignore; ¿qué sintaxis de comentario puedes usar?", cod="<?php // nota ignorada\necho 'Visible';", h="ignora una nota y muestra solo el texto visible", pr=("Una forma común de comentario de línea empieza con ___.", "//"), ec="usar <!-- --> como si fuera un comentario PHP", pr2=("El comentario iniciado con // no se ___ al ejecutar.", "ejecuta"), out="Visible"),
K("Salida con echo", d="constructo del lenguaje que envía uno o varios valores a la salida", u="mostrar texto o resultados calculados", mas="echo no es una función y puede recibir varios argumentos separados por comas. No devuelve un valor que se pueda asignar; se usa para producir salida.", k=["echo puede mostrar varios argumentos separados por comas.", "echo es un constructo del lenguaje y no requiere paréntesis.", "echo no devuelve un valor para guardarlo en una variable."], sit="Quieres mostrar texto y un número en una sola instrucción; ¿qué constructo de PHP eliges?", cod="<?php echo 'Puntos: ', 7;", h="muestra una etiqueta y el número siete", pr=("El constructo habitual para mostrar salida es ___.", "echo"), ec="tratar echo como una función que devuelve el texto mostrado", pr2=("echo puede mostrar varios valores separados por ___.", "comas"), out="Puntos: 7"),
K("Asignación", d="operación con = que guarda un valor en una variable", u="crear o actualizar el contenido asociado a un nombre", mas="El operador = asigna el valor de la derecha a la variable de la izquierda. No comprueba igualdad: para comparar valores se usan operadores como ===.", k=["= asigna el valor de la expresión derecha.", "La asignación puede inicializar o reemplazar un valor.", "=== compara estrictamente y no asigna."], sit="Un puntaje debe actualizarse con el resultado de un cálculo y no compararse con él; ¿qué operación haces?", cod="<?php $puntos = 4; $puntos += 2; echo $puntos;", h="inicializa y actualiza una variable", pr=("El operador básico que asigna un valor es ___.", "="), ec="confundir la asignación = con la comparación estricta ===", pr2=("El puntaje actualizado queda en ___.", "6"), out="6"),
K("Variables con dólar", d="nombres que empiezan con $ y contienen un valor", u="guardar datos para reutilizarlos en expresiones", mas="Una variable PHP comienza con el signo $. Se asigna con =, y PHP determina el tipo a partir del valor asignado; el nombre distingue mayúsculas de minúsculas.", k=["El nombre de una variable PHP empieza con $.", "La asignación de una variable utiliza =.", "$total y $Total son variables distintas."], sit="Quieres guardar el nombre de una persona en una variable PHP; ¿qué prefijo necesita el nombre?", cod="<?php $nombre = 'Luz'; echo $nombre;", h="guarda y muestra un nombre", pr=("El carácter inicial de una variable PHP es ___.", "$"), ec="escribir el signo $ después del nombre de variable", pr2=("El operador de asignación de variables es ___.", "="), out="Luz"),
K("Nombres de variables", d="identificadores que nombran variables y siguen reglas de escritura", u="crear nombres válidos y legibles para los datos", mas="Después de $, el nombre de variable debe comenzar con una letra o guion bajo; también puede contener números después del primer carácter. Los nombres de variables distinguen mayúsculas y minúsculas.", k=["$valor2 es un nombre válido porque empieza con letra.", "$_total es válido porque el guion bajo puede iniciar el nombre.", "$dato y $Dato son nombres distintos."], sit="Necesitas un nombre PHP que empiece con guion bajo y luego incluya un número; ¿qué regla sigues?", cod="<?php $item2 = 'caja'; echo $item2;", h="usa un identificador que termina con un dígito", pr=("¿Cuál es un nombre de variable PHP válido?", "$item2"), ec="iniciar el nombre de variable con un dígito", pr2=("Una variable PHP puede empezar con letra o guion ___.", "bajo"), out="caja"),
K("Tipos dinámicos", d="comportamiento donde una variable puede contener valores de distintos tipos", u="asignar distintos valores sin declarar previamente un tipo fijo", mas="PHP asocia un tipo con cada valor y permite reasignar una variable a otro tipo. Las declaraciones de tipo y el modo estricto pueden imponer comprobaciones en funciones, pero no convierten todas las variables en estáticas.", k=["Una variable PHP puede cambiar de tipo tras una nueva asignación.", "El tipo pertenece al valor que contiene la variable.", "Las declaraciones de tipos permiten restringir parámetros y retornos."], sit="Un contador primero guarda un entero y después recibe un texto sin declaración de tipo; ¿qué comportamiento permite esto?", cod="<?php $dato = 5; $dato = 'cinco'; echo $dato;", h="reasigna una variable primero a entero y luego a texto", pr=("PHP permite que las variables cambien de tipo; su tipado es ___.", "dinámico"), ec="pensar que una variable conserva siempre el tipo de su primera asignación", pr2=("Después de asignarle 'cinco', $dato contiene un ___.", "texto"), out="cinco"),
K("Tipo entero", d="tipo int que representa números enteros sin parte decimal", u="contar unidades y realizar operaciones con números enteros", mas="Los literales enteros pueden escribirse en decimal y otras bases. El tamaño máximo depende de la plataforma, por lo que cálculos que exceden el rango entero pueden convertirse en float.", k=["PHP representa los enteros con el tipo int.", "El literal 42 es un entero decimal.", "El rango de int depende de la plataforma."], sit="Quieres guardar la cantidad de libros, sin fracción decimal; ¿qué tipo de dato corresponde?", cod="<?php $libros = 4; echo $libros + 3;", h="suma dos cantidades enteras", pr=("El tipo PHP para números enteros se llama ___.", "int"), ec="guardar una cantidad entera como texto entre comillas sin necesidad", pr2=("El resultado de sumar 4 y 3 es ___.", "7"), out="7"),
K("Tipo float", d="tipo numérico que representa valores con parte fraccionaria", u="expresar mediciones y cálculos decimales aproximados", mas="Los valores decimales como 2.5 son de tipo float. La representación binaria puede aproximar algunos decimales, así que para dinero se suelen usar unidades menores enteras o bibliotecas decimales.", k=["2.5 es un literal float en PHP.", "Los float pueden representar ciertos decimales de forma aproximada.", "No conviene comparar cálculos monetarios float esperando exactitud decimal absoluta."], sit="Una medición tiene una parte fraccionaria y se modela como valor binario aproximado; ¿qué tipo PHP usas?", cod="<?php $metros = 1.5; echo $metros * 2;", h="duplica una medida decimal", pr=("El tipo numérico que puede contener decimales se llama ___.", "float"), ec="suponer que todo cálculo float conserva exactitud decimal perfecta", pr2=("El doble de 1.5 es ___.", "3"), out="3"),
K("Tipo booleano", d="tipo bool con uno de dos valores: true o false", u="representar condiciones verdaderas o falsas", mas="Los booleanos son útiles en decisiones y resultados de comparaciones. Se escriben true y false sin comillas; entre comillas serían cadenas de texto.", k=["true y false son los dos literales booleanos de PHP.", "Una comparación como 3 < 5 produce un bool.", "Los textos 'true' y 'false' son cadenas, no booleanos."], sit="Quieres guardar si una puerta está abierta como estado verdadero o falso; ¿qué tipo eliges?", cod="<?php $abierta = true; echo $abierta;", h="muestra el valor booleano verdadero como 1", pr=("El tipo PHP de true y false es ___.", "bool"), ec="escribir true entre comillas y convertirlo accidentalmente en texto", pr2=("La comparación 3 < 5 produce ___.", "true"), out="1"),
K("Valor null", d="valor especial que representa la ausencia de un valor", u="indicar explícitamente que una variable no contiene un dato", mas="null es un valor único y se escribe sin comillas. Una variable asignada a null se considera no definida para isset, aunque la variable sí fue asignada.", k=["null representa la ausencia de un valor.", "null no es lo mismo que la cadena vacía ''.", "isset($x) devuelve false si $x contiene null."], sit="Un campo aún no tiene dato y quieres representarlo explícitamente; ¿qué valor especial utilizas?", cod="<?php $nota = null; var_export($nota === null);", h="comprueba estrictamente que la variable sea null", pr=("El valor especial que representa ausencia de dato es ___.", "null"), ec="confundir null con una cadena vacía", pr2=("La comparación estricta de null con null produce ___.", "true"), out="true"),
K("Cadenas de texto", d="valores string formados por caracteres entre comillas", u="guardar palabras y mensajes para procesarlos", mas="PHP admite cadenas entre comillas simples y dobles. Las comillas dobles reconocen interpolación de variables y secuencias de escape habituales; las simples tienen una interpretación más limitada.", k=["'Hola' y \"Hola\" crean cadenas PHP.", "Las comillas dobles permiten interpolar variables.", "Una cadena vacía sigue siendo un valor string."], sit="Quieres almacenar la palabra PHP como texto literal; ¿qué tipo de valor eliges?", cod="<?php $saludo = 'Hola'; echo $saludo;", h="guarda y muestra una cadena", pr=("El tipo PHP para texto se llama ___.", "string"), ec="olvidar cerrar la comilla de una cadena", pr2=("La cadena del ejemplo contiene la palabra ___.", "Hola"), out="Hola"),
K("Interpolación", d="inserción de valores de variables dentro de cadenas con comillas dobles", u="construir mensajes que combinan texto y valores", mas="En cadenas con comillas dobles PHP sustituye variables simples por su valor. Las llaves permiten delimitar con claridad el nombre de una variable junto a otros caracteres.", k=["La interpolación directa funciona en cadenas con comillas dobles.", "Las cadenas con comillas simples no interpolan variables.", "Las llaves delimitan el nombre interpolado, como {$nombre}."], sit="Quieres que una variable aparezca dentro de una frase entre comillas dobles; ¿qué mecanismo aplicas?", cod="<?php $nombre = 'Mia'; echo \"Hola, $nombre\";", h="inserta el valor de nombre dentro del saludo", pr=("Insertar una variable dentro de una cadena doble se llama ___.", "interpolación"), ec="esperar que una cadena con comillas simples sustituya variables", pr2=("El saludo interpolado dice ___.", "Hola, Mia"), out="Hola, Mia"),
K("Concatenación con punto", d="operación que une cadenas usando el operador punto", u="combinar fragmentos de texto en una cadena", mas="En PHP el punto concatena cadenas. El operador + se reserva para suma numérica, por lo que no es el operador de concatenación.", k=["El operador . concatena cadenas en PHP.", "El operador + realiza suma numérica.", "La asignación .= concatena y guarda el resultado en la misma variable."], sit="Necesitas unir dos fragmentos de texto sin sumarlos; ¿qué operador usas en PHP?", cod="<?php echo 'PHP', ' ', '8';", h="muestra tres fragmentos unidos por echo", pr=("El operador de concatenación de PHP es ___.", "."), ec="usar + para unir dos cadenas como en algunos lenguajes", pr2=("El operador de concatenación es el punto, no el signo ___.", "+"), out="PHP 8"),
K("Constantes con const", d="identificadores sin prefijo dólar cuyo valor no se reasigna", u="nombrar valores que permanecen fijos durante la ejecución", mas="Una constante declarada con const tiene nombre sin $. Las constantes de esta forma se definen en ámbito de archivo o clase, no dentro de bloques condicionales.", k=["const LIMITE = 10; declara una constante.", "Las constantes declaradas con const no llevan $.", "Una constante no se reasigna tras su definición."], sit="Un límite fijo debe tener un nombre sin dólar y no cambiar después de declararse; ¿qué declaras?", cod="<?php const LIMITE = 12; echo LIMITE;", h="declara una constante y muestra su valor", pr=("La palabra clave para declarar una constante es ___.", "const"), ec="anteponer $ al nombre de una constante", pr2=("Las constantes definidas con const se usan sin el signo ___.", "$"), out="12"),
K("Inspección con var_dump", d="constructo que imprime información estructurada de tipo y valor", u="examinar con precisión el contenido de una variable", mas="var_dump muestra el tipo y el valor, y en cadenas también su longitud. Es una herramienta útil para depuración, aunque el formato no es adecuado como presentación para usuarios.", k=["var_dump muestra el tipo y el valor de sus argumentos.", "En cadenas var_dump informa la longitud.", "La salida de var_dump es útil para depurar, no para una interfaz final."], sit="Una salida de echo oculta si un valor es texto o número y necesitas ver tipo y valor; ¿qué usas?", cod="<?php var_dump(42);", h="muestra el tipo entero y el valor 42", pr=("El constructo que inspecciona tipo y valor es ___.", "var_dump"), ec="mostrar la salida de depuración var_dump directamente a usuarios finales", pr2=("La salida de var_dump(42) comienza con ___.", "int(42)"), out="int(42)"),
K("Secuencias de escape", d="combinaciones como \\n que representan caracteres especiales en cadenas", u="incluir saltos de línea y tabulaciones en texto", mas="Las cadenas con comillas dobles interpretan secuencias como \\n para nueva línea y \\t para tabulación. Las cadenas con comillas simples interpretan menos secuencias, principalmente \\\\ y \\'.", k=["\\n representa una nueva línea en una cadena doble.", "\\t representa una tabulación en una cadena doble.", "Las cadenas simples no interpretan \\n como salto de línea."], sit="Un texto debe contener un carácter de nueva línea representado por una secuencia dentro de una cadena; ¿qué sintaxis usas?", cod='<?php echo strlen("A\\nB");', h="cuenta tres caracteres en una cadena que incluye un salto de línea", pr=("La secuencia de escape para nueva línea es ___.", "\\n"), ec="suponer que '\\n' entre comillas simples equivale a un salto de línea", pr2=("La cadena con A, salto y B contiene ___ caracteres.", "3"), out="3"),
